declarations.code:
template <class T>

T atomic_fetch_xor(std::atomic<T> *obj,

    typename std::atomic<T>::value_type arg) noexcept;

template <class T>

T atomic_fetch_xor(volatile std::atomic<T> *obj,

    typename std::atomic<T>::value_type arg) noexcept;

examples.code:
#include <atomic>
#include <iostream>

int main() {
    std::atomic<unsigned> flags{10};
    std::cout << std::atomic_fetch_xor(&flags, 3u) << " -> " << flags.load() << "\n";
    std::cout << std::atomic_fetch_xor_explicit(&flags, 1u, std::memory_order_seq_cst)
              << " -> " << flags.load() << "\n";
}
